        out.height = sideGap * underLip * slopeHeight + striation * 0.12 + (chip - 0.5) * 0.06;
        const shade = lerp2(0.68, 0.94 + (tileId - 0.5) * 0.11, sideGap * underLip) + (striation - 0.5) * 0.08;
        out.r = shade + (tileId - 0.5) * 0.03;
