        const warpZ = Math.sign(sz) * Math.pow(Math.abs(sz), 1.62);
        const jitterX = (seededRand(i * 1.73 + 0.1) - 0.5) * 0.36;
        const jitterZ = (seededRand(i * 2.91 + 0.7) - 0.5) * 0.36;
        const wx = clamp5(warpX * 44.5 + jitterX, -45.5, 45.5);
