      matArr[base + 1] = 0;
      matArr[base + 2] = 0;
      matArr[base + 3] = 0;
      matArr[base + 4] = 0;
      matArr[base + 5] = s;
      matArr[base + 6] = 0;
      matArr[base + 7] = 0;
      matArr[base + 8] = 0;
      matArr[base + 9] = 0;
      matArr[base + 10] = s;
      matArr[base + 11] = 0;
      matArr[base + 12] = wx;
