      this.lilyMesh = new InstancedMesh(lilyGeo, lilyMat, MAX_LILIES);
      this.lilyMesh.name = "TinyGladeWaterLilies";
      this.lilyMesh.count = 0;
      this.lilyMesh.receiveShadow = true;
      this.lilyMesh.frustumCulled = false;
